<script setup>
import { reactive } from 'vue'
import { Head, router, useForm } from '@inertiajs/vue3'
import AdminLayout from '../../../Layouts/AdminLayout.vue'
import PageHeader from '../../../Components/Ui/PageHeader.vue'
import AccountingNav from '../../../Components/Accounting/AccountingNav.vue'
import AccountingPanel from '../../../Components/Accounting/AccountingPanel.vue'
import Pagination from '../../../Components/Ui/Pagination.vue'
import { useConfirm } from '../../../Composables/useConfirm'
defineOptions({layout:AdminLayout})
const props=defineProps({assets:Object,stats:Object,statusLabels:Object,categories:Array,filters:Object,defaultPeriodMonth:String,defaultPostedOn:String,can:Object,currency:Object,urls:Object});const {ask}=useConfirm();const filter=reactive({status:props.filters.status||'',category:props.filters.category||'',search:props.filters.search||''});const depreciation=useForm({period_month:props.defaultPeriodMonth,posted_on:props.defaultPostedOn,notes:''});const money=v=>`${new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0))} ${props.currency.symbol}`;const visit=()=>router.get(props.urls.index,filter,{preserveState:true,preserveScroll:true});async function run(){const yes=await ask({title:'ترحيل إهلاك الشهر؟',message:'سيُرحّل النظام الإهلاك لكل أصل نشط ومستحق، ويتخطى ما رُحّل لنفس الشهر.',confirmLabel:'ترحيل الإهلاك'});if(yes)depreciation.post(props.urls.runDepreciation,{preserveScroll:true})}
</script>
<template><Head title="الأصول الثابتة"/><PageHeader title="الأصول الثابتة" icon="bi-building-gear" subtitle="سجل المعدات والأثاث، ورحّل الإهلاك دون جداول خارجية"><template #actions><a v-if="can.create" :href="urls.create" class="btn btn-primary"><i class="bi bi-plus-lg"></i> أصل جديد</a></template></PageHeader><AccountingNav :urls="urls" active="fixedAssets"/><div class="asset-stats"><article><span><i class="bi bi-box-seam"></i></span><div><small>عدد الأصول</small><strong>{{stats.count}}</strong></div></article><article><span><i class="bi bi-check2-circle"></i></span><div><small>أصول نشطة</small><strong>{{stats.active}}</strong></div></article><article><span><i class="bi bi-cash-stack"></i></span><div><small>إجمالي التكلفة</small><strong>{{money(stats.cost)}}</strong></div></article><article><span><i class="bi bi-wallet2"></i></span><div><small>القيمة الدفترية</small><strong>{{money(stats.book)}}</strong></div></article></div><form class="filters" @submit.prevent="visit"><label><span>الحالة</span><select v-model="filter.status" class="form-select"><option value="">كل الحالات</option><option v-for="(label,key) in statusLabels" :key="key" :value="key">{{label}}</option></select></label><label><span>الفئة</span><select v-model="filter.category" class="form-select"><option value="">كل الفئات</option><option v-for="item in categories" :key="item" :value="item">{{item}}</option></select></label><label class="search"><span>بحث</span><div><i class="bi bi-search"></i><input v-model="filter.search" type="search" placeholder="رقم الأصل، الاسم، المورد..."></div></label><button class="btn btn-primary">بحث</button></form><AccountingPanel v-if="can.update" title="إهلاك شهر كامل" description="تشغيل واحد لكل الأصول النشطة؛ يتخطى المكرر أو غير المستحق تلقائياً." icon="bi-calendar-check" tone="amber"><form class="batch" @submit.prevent="run"><label><span>الشهر</span><input v-model="depreciation.period_month" type="month" class="form-control" required></label><label><span>تاريخ القيد</span><input v-model="depreciation.posted_on" type="date" class="form-control" required></label><label><span>ملاحظات</span><input v-model="depreciation.notes" class="form-control" placeholder="اختياري"></label><button class="btn btn-warning" :disabled="depreciation.processing"><i class="bi bi-journal-check"></i> ترحيل الإهلاك</button></form></AccountingPanel><AccountingPanel title="سجل الأصول" :description="`${assets.total} أصل مسجل`" icon="bi-building-gear" compact><div class="assets"><a v-for="asset in assets.data" :key="asset.id" :href="asset.showUrl"><span class="asset-icon"><i class="bi bi-building-gear"></i></span><div><strong>{{asset.name}}</strong><small>{{asset.number}} · {{asset.vendor||asset.category||'بدون تصنيف'}}</small></div><time>{{asset.date}}</time><span><small>التكلفة</small><bdi>{{money(asset.cost)}}</bdi></span><span><small>مجمع الإهلاك</small><bdi>{{money(asset.accumulated)}}</bdi></span><span class="book"><small>القيمة الدفترية</small><bdi>{{money(asset.bookValue)}}</bdi></span><em :data-status="asset.status">{{statusLabels[asset.status]||asset.status}}</em><i class="bi bi-chevron-left"></i></a><div v-if="!assets.data.length" class="empty"><i class="bi bi-building-x"></i><strong>لا توجد أصول ثابتة</strong><span>أضف المعدات أو الأثاث الذي تريد إهلاكه محاسبياً.</span></div></div><template #footer><Pagination :links="assets.links"/></template></AccountingPanel></template>
<style scoped>.asset-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:10px}.asset-stats article{display:flex;align-items:center;gap:9px;padding:11px;border:1px solid #dfe7e2;border-radius:13px;background:#fff}.asset-stats article>span{display:grid;width:36px;height:36px;place-items:center;border-radius:10px;color:#1f6b50;background:#e9f4ed}.asset-stats article>div{display:grid}.asset-stats small{color:#7d8a82;font-size:.58rem}.asset-stats strong{font-size:.76rem}.filters{display:grid;grid-template-columns:180px 200px 1fr auto;align-items:end;gap:8px;margin-bottom:10px;padding:10px;border:1px solid #dfe7e2;border-radius:13px;background:#fff}.filters label,.batch label{display:grid;gap:4px}.filters label>span,.batch label>span{font-size:.61rem;font-weight:850}.search>div{display:flex;align-items:center;gap:6px;padding:0 9px;border:1px solid #dfe7e2;border-radius:8px}.search input{width:100%;padding:8px 0;border:0;outline:0;font-size:.67rem}.batch{display:grid;grid-template-columns:170px 180px 1fr auto;align-items:end;gap:8px}.assets{display:grid}.assets>a{display:grid;grid-template-columns:34px minmax(160px,1fr) 85px repeat(3,minmax(90px,.55fr)) 75px 18px;align-items:center;gap:8px;padding:10px 13px;border-bottom:1px solid #edf1ee;color:#35463b}.asset-icon{display:grid;width:32px;height:32px;place-items:center;border-radius:9px;color:#1f6b50;background:#e9f4ed}.assets>a>div{display:grid}.assets>a>div strong{font-size:.67rem}.assets>a>div small,.assets time,.assets>a>span small{color:#819087;font-size:.55rem}.assets>a>span:not(.asset-icon){display:grid}.assets>a>span bdi{font-size:.61rem;font-weight:800}.assets .book bdi{color:#1f6b50}.assets a em{padding:3px 6px;border-radius:999px;color:#1f6b50;background:#e7f4eb;font-size:.54rem;font-style:normal;text-align:center}.assets a em[data-status=disposed]{color:#66746b;background:#eef2ef}.assets a>i{font-size:.52rem}.empty{display:grid;justify-items:center;gap:4px;padding:55px;color:#839087}.empty i{font-size:1.4rem}.empty strong{font-size:.72rem}.empty span{font-size:.61rem}@media(max-width:1050px){.asset-stats{grid-template-columns:1fr 1fr}.filters{grid-template-columns:1fr 1fr}.filters .search{grid-column:1/-1}.batch{grid-template-columns:1fr 1fr}.batch label:nth-child(3){grid-column:1/-1}.assets>a{grid-template-columns:34px 1fr auto auto}.assets time,.assets>a>span:not(.book):not(.asset-icon){display:none}.assets .book{grid-column:3}.assets a em{grid-column:4}.assets a>i{display:none}}@media(max-width:560px){.asset-stats{grid-template-columns:1fr 1fr}.filters,.batch{grid-template-columns:1fr}.filters .search,.batch label:nth-child(3){grid-column:auto}}</style>
